import React from 'react';
import { render } from 'react-dom';
import { DataTable } from 'carbon-components-react';
import Edit16 from '@carbon/icons-react/lib/edit/16';
import Reset16 from '@carbon/icons-react/lib/refresh/16';
import Close16 from '@carbon/icons-react/lib/close/16';

const { 
  TableContainer, Table, TableHead, TableRow, TableHeader,
  TableBody, TableCell,
  TableToolbar, TableToolbarSearch, TableBatchActions, TableBatchAction,
  TableSelectAll, TableSelectRow,
} = DataTable;

const rows = [
  { id: 'a', name: 'Row A' },
  { id: 'b', name: 'Row B' },
];

const headers = [
  { key: 'name', header: 'Name' },
];

function Example({ showIconDescription }) {
  return (
    <DataTable rows={rows} headers={headers} isSortable render={({
      rows, headers, getHeaderProps, getSelectionProps,
      getBatchActionProps, onInputChange, selectedRows
    }) => (
      <TableContainer title={
        showIconDescription ?
          'TableBatchAction with iconDescription provided' :
          'TableBatchAction with iconDescription not provided'
      }>
        <TableToolbar>
          <TableBatchActions {...getBatchActionProps()}>
            <TableBatchAction
              renderIcon={Edit16}
              onClick={() => alert('Edit clicked')}
              {...(showIconDescription
                ? { iconDescription: '' }
                : {})}
            >
              Edit
            </TableBatchAction>
            <TableBatchAction
              renderIcon={Reset16}
              onClick={() => alert('Reset clicked')}
              {...(showIconDescription
                ? { iconDescription: '' }
                : {})}
            >
              Reset
            </TableBatchAction>
            <TableBatchAction
              renderIcon={Close16}
              onClick={() => alert('Cancel clicked')}
              {...(showIconDescription
                ? { iconDescription: '' }
                : {})}
            >
              Cancel
            </TableBatchAction>
          </TableBatchActions>
          <TableToolbarSearch onChange={onInputChange} />
        </TableToolbar>
        <Table>
          <TableHead>
            <TableRow>
              <TableSelectAll {...getSelectionProps()} />
              {headers.map(header => (
                <TableHeader key={header.key} {...getHeaderProps({ header })}>
                  {header.header}
                </TableHeader>
              ))}
            </TableRow>
          </TableHead>
          <TableBody>
            {rows.map(row => (
              <TableRow key={row.id}>
                <TableSelectRow {...getSelectionProps({ row })} />
                {row.cells.map(cell => (
                  <TableCell key={cell.id}>{cell.value}</TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    )} />
  );
}

function App() {
  return (
    <>
      <Example showIconDescription={false} />
      <hr />
      <Example showIconDescription={true} />
    </>
  );
}

render(<App />, document.getElementById('root'));
